package com.landportal.controller; import com.landportal.repository.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/notifications") public class NotificationController{final NotificationRepository n;final UserRepository u;public NotificationController(NotificationRepository n,UserRepository u){this.n=n;this.u=u;}@GetMapping List<?> all(Authentication a){return n.findByUserIdOrderByCreatedAtDesc(u.findByEmail(a.getName()).orElseThrow().getId());}@PutMapping("/{id}/read") Object read(@PathVariable Long id,Authentication a){var x=n.findById(id).orElseThrow();var user=u.findByEmail(a.getName()).orElseThrow();if(!x.getUser().getId().equals(user.getId()))throw new RuntimeException("Access denied");x.setReadStatus(true);return n.save(x);}}
